INSERT INTO reviews (id, donation_id, user_id, rating, comment, helpful_count, created_at, updated_at, deleted_at) VALUES
  ('60000000-0000-4000-8000-000000000001', '40000000-0000-4000-8000-000000000001', 'e13f2687-fd8e-4f96-a360-871858c1acad', 5, 'プログラミングの品質向上に大変役立ちました。具体例が豊富で理解しやすい。', 0, '2025-09-04 01:22:38.19821+00', '2025-09-04 04:22:04.676111+00', NULL),
  ('60000000-0000-4000-8000-000000000002', '40000000-0000-4000-8000-000000000002', 'b3f11c4a-0d57-450c-a429-a7138e1f3d75', 4, '初心者にもわかりやすく、実践的な内容。チーム全体で読むべき本。', 0, '2025-09-04 01:22:38.19821+00', '2025-09-04 04:22:04.676111+00', NULL),
  ('60000000-0000-4000-8000-000000000003', '40000000-0000-4000-8000-000000000008', '0bf9509d-24fe-42b2-8cbd-8a82a3ca82d3', 5, 'Docker入門には最適。実際の運用事例も参考になる。', 0, '2025-09-04 01:22:38.19821+00', '2025-09-04 04:22:04.676111+00', NULL),
  ('60000000-0000-4000-8000-000000000004', '40000000-0000-4000-8000-000000000010', '7778b5eb-b559-4239-aecd-97f4d49c333b', 4, '問題解決の思考法が体系化されており、業務に活かせる内容。', 0, '2025-09-04 01:22:38.19821+00', '2025-09-04 04:22:04.676111+00', NULL),
  ('60000000-0000-4000-8000-000000000005', '40000000-0000-4000-8000-000000000013', '33ceed5e-3dbb-48c1-bc9f-83f4f4d5f79e', 5, 'マウスの操作性が素晴らしく、作業効率が大幅に向上した。', 0, '2025-09-04 01:22:38.19821+00', '2025-09-04 04:22:04.676111+00', NULL),
  ('60000000-0000-4000-8000-000000000006', '40000000-0000-4000-8000-000000000015', 'b3f11c4a-0d57-450c-a429-a7138e1f3d75', 5, '4K表示でデザイン作業が格段にやりやすくなった。色再現性も優秀。', 0, '2025-09-04 01:22:38.19821+00', '2025-09-04 04:22:04.676111+00', NULL)
