-- =================================================
-- 社内寄贈物管理システム - シードファイル
-- 開発環境のデータをもとにした初期データ投入
-- =================================================

-- =================================================
-- Phase 1: 独立テーブル（依存関係なし）
-- 実行順序: users → categories → locations → tags
-- =================================================

-- 1. users テーブル
ON CONFLICT (id) DO NOTHING;


-- 2. categories テーブル  
ON CONFLICT (id) DO NOTHING;


-- 3. locations テーブル
ON CONFLICT (id) DO NOTHING;


-- 4. tags テーブル
ON CONFLICT (id) DO NOTHING;


-- =================================================
-- Phase 2: 第一レベル依存テーブル
-- 実行順序: sub_categories
-- =================================================

-- 5. sub_categories テーブル（categories依存）
ON CONFLICT (id) DO NOTHING;


-- =================================================
-- Phase 3: 第二レベル依存テーブル
-- 実行順序: donations
-- =================================================

-- 6. donations テーブル（users, categories, sub_categories, locations依存）
ON CONFLICT (id) DO NOTHING;


-- =================================================
-- Phase 4: 関連テーブル（donations依存）
-- 実行順序: donation_images → donation_tags → lendings → reviews → favorites
-- =================================================

-- 7. donation_images テーブル（donations依存）
ON CONFLICT (id) DO NOTHING;


-- 8. donation_tags テーブル（donations + tags依存）
ON CONFLICT (id) DO NOTHING;

-- 9. lendings テーブル（donations + users依存）
ON CONFLICT (id) DO NOTHING;


-- 10. reviews テーブル（donations + users依存）
ON CONFLICT (id) DO NOTHING;


-- 11. favorites テーブル（donations + users依存）
ON CONFLICT (id) DO NOTHING;


-- =================================================
-- 実行完了確認
-- =================================================

